const reserved=(pid,s)=>ORDERS.filter(o=>o.s===s&&RES_ST.includes(o.st)).reduce((a,o)=>a+o.it.filter(i=>i[0]===pid).reduce((b,i)=>b+i[1],0),0);
const onHand=(pid,s)=>PR(pid).st[s][0];
const freeQ=(pid,s)=>onHand(pid,s)-reserved(pid,s);
const lineSum=i=>{const p=PR(i[0]);return i[2]==='u'&&p.u?p.u[2]*i[1]:p.price*i[1]};
const oSum=o=>o.it.reduce((a,i)=>a+lineSum(i),0);
const oQty=o=>o.it.reduce((a,i)=>a+i[1],0);
const cSum=c=>c.it.reduce((a,i)=>a+lineSum(i),0);
const ost=k=>{const s=OSTOF(k);return `<span class="st" style="--sc:${s.c}">${esc(s.n)}</span>`};
const mpm=k=>`<span class="mpm" style="--c:${MP[k].c}">${esc(MP[k].s)}</span>`;
const catm=k=>`<span class="catm" style="--c:${CATS[k].c}">${CATS[k].s}</span>`;
const stm=s=>`<span class="stm">${STORES[s].s}</span>`;
const ordL=id=>`<a class="lk mono" onclick="event.stopPropagation();openOrd('${id}')">${esc(id)}</a>`;
const prL=id=>`<a class="lk" onclick="event.stopPropagation();card('pr','${id}')">${esc(PR(id).n)}</a>`;
const vatSplit=items=>{const r={};items.forEach(i=>{const p=PR(i[0]),v=vatOf(p);r[v]=(r[v]||0)+lineSum(i)});return r};
const vatLine=items=>{const r=vatSplit(items);return Object.keys(r).sort((a,b)=>a-b).map(v=>`НДС ${v}%: ${tg(vatSum(r[v],+v))}`).join(' · ')};
const SO=()=>ORDERS.filter(o=>inStore(o.s));
const cnt=k=>SO().filter(o=>o.st===k).length;
const uAb=p=>({блистер:'бл.',пакетик:'пак.',маска:'шт.'})[p.u[0]]||'шт.';
const uPl=(p,n)=>plural(n,{блистер:['блистер','блистера','блистеров'],пакетик:['пакетик','пакетика','пакетиков'],маска:['маска','маски','масок']}[p.u[0]]||['шт.','шт.','шт.']);
const isPickup=o=>o.dlv.indexOf('Самовывоз')===0;
let tcN={A1:458,A2:319},fcN={A1:18825,A2:7418};
function fefoTake(pid,s,q){BATCHES.filter(b=>b.p===pid&&b.s===s&&b.q>0).sort((a,b)=>a.exp<b.exp?-1:1).forEach(b=>{const t=Math.min(b.q,q);b.q-=t;q-=t})}
function issue(o,how){o.st='done';const n=fcN[o.s]++;o.fc=`ФЧ-${o.s[1]}-0${n}`;o.it.forEach(i=>{PR(i[0]).st[o.s][0]-=i[1];fefoTake(i[0],o.s,i[1])});
 CHECKS.unshift({no:o.fc,s:o.s,t:NOW,src:o.mp,ord:o.id,it:o.it.map(i=>i.slice()),pay:MP[o.mp].s,ofd:'ok'});o.h.push([NOW,how+' → фискальный чек '+o.fc+' ушёл в ОФД'+(o.it.some(i=>PR(i[0]).mk)?', коды маркировки выведены из оборота в ИС МПТ':'')]);o.dlv=o.dlv.split(' · ')[0]+' · выдан '+NOW}
function ordAdv(id){const o=OR(id);if(!o)return;let m='';
 if(o.st==='new'){const short=o.it.filter(i=>freeQ(i[0],o.s)<i[1]);if(short.length){toast(`Не хватает на ${stName(o.s)}: ${short.map(i=>esc(PR(i[0]).n)+' — нужно '+i[1]+', свободно '+freeQ(i[0],o.s)).join('; ')}. Сделайте перемещение с другой аптеки.`);return}
  o.st='res';o.tc=`ТЧ-${o.s[1]}-0${tcN[o.s]++}`;TCHECKS.unshift({no:o.tc,ord:o.id,s:o.s,d:TODAY,st:'res'});o.h.push([NOW,`Резерв на ${stName(o.s)}: ${oQty(o)} ${plural(oQty(o),['позиция','позиции','позиций'])} убраны из свободного остатка · товарный чек ${o.tc}`]);m=`Резерв поставлен: на Kaspi, Halyk и Forte остаток уменьшился сразу. Распечатан <b>товарный чек ${o.tc}</b> — фискального пока нет.`}
 else if(o.st==='res'){o.st='pack';o.h.push([NOW,'Собран · '+(STAFF[ROLES[role].p]||'сотрудник')]);m='Заказ собран. Следующий шаг — передать курьеру или выдать в аптеке.'}
 else if(o.st==='pack'){if(isPickup(o)){issue(o,'Выдан в аптеке');m=`Выдан в аптеке. <b>Фискальный чек ${o.fc}</b> пробит автоматически, товар списан с ${stName(o.s)}.`}else{o.st='courier';o.h.push([NOW,'Передан курьеру '+MP[o.mp].s]);m='Передан курьеру. Резерв держится, пока площадка не пришлёт «выдан» или «отказ».'}}
 else if(o.st==='courier'){issue(o,MP[o.mp].s+': выдан клиенту');m=`${MP[o.mp].s} прислал «выдан». <b>Фискальный чек ${o.fc}</b> ушёл в ОФД автоматически — руками ничего вводить не нужно.`}
 tcSync();render();if(document.getElementById('mbg').classList.contains('show'))card('ord',id);toast(m)}
function ordRefuse(id){const o=OR(id);if(!o)return;
 if(['new','res','pack'].includes(o.st)){o.st='back';o.why='Отменён до передачи курьеру';o.h.push([NOW,'Отмена до отправки · резерв снят, товар на полке']);toast('Заказ отменён до отправки — резерв снят сразу, чек не пробивался.')}
 else if(o.st==='courier'){o.st='refuse';o.why='Отказ клиента при доставке';o.h.push([NOW,MP[o.mp].s+': отказ клиента · товар везут назад']);toast('Отказ: товар в пути обратно. Резерв держится до тех пор, пока вы не подтвердите, что товар вернулся.')}
 tcSync();render();if(document.getElementById('mbg').classList.contains('show'))card('ord',id)}
function ordBack(id){const o=OR(id);if(!o||o.st!=='refuse')return;o.st='back';o.arrived=true;o.h.push([NOW,`Возврат принят · ${STAFF[ROLES[role].p]||'сотрудник'}: резерв снят, ${oQty(o)} шт. снова свободны на ${stName(o.s)}`]);o.dlv=o.dlv.split(' · ')[0]+' · возврат принят '+NOW;tcSync();render();if(document.getElementById('mbg').classList.contains('show'))card('ord',id);
 toast(`Возврат принят: резерв снят, товар снова в продаже на ${stName(o.s)} и на площадках. <b>Фискальный чек не пробивался</b> — возвращать через ОФД нечего, коды маркировки остались в обороте.`)}
function tcSync(){TCHECKS.forEach(t=>{const o=OR(t.ord);if(o)t.st=o.st})}
function setStore(s){const lock=ROLES[role].st;if(lock&&s!==lock&&s!=='all'){toast(`Роль «${esc(role)}» работает только со своей аптекой — так настроены права.`);return}store=s;buildSync();render()}

/* ===== Пульт дня ===== */
SC.today=()=>{const O=SO();const ch=CHECKS.filter(c=>inStore(c.s));
 const lanes=OST.map(s=>({s,n:O.filter(o=>o.st===s.k).length}));
 const rev={};Object.keys(MP).forEach(k=>rev[k]={A1:0,A2:0});ch.forEach(c=>rev[c.src][c.s]+=cSum(c));
 const tot=Object.values(rev).reduce((a,r)=>a+r.A1+r.A2,0);
 const AL=[];
 O.filter(o=>o.st==='new').forEach(o=>AL.push(['b',`Новый заказ ${MP[o.mp].s} ${o.id}`,`${esc(o.cl)} · ${oQty(o)} шт. · ${tg(oSum(o))} · ${stName(o.s)} — поставить в резерв`,`openOrd('${o.id}')`]));
 O.filter(o=>o.st==='refuse'&&o.arrived).forEach(o=>AL.push(['r',`Отказ ${o.id} привезли в аптеку`,`Подтвердите, что товар на месте — резерв снимется, остаток восстановится`,`openOrd('${o.id}')`]));
 O.filter(o=>o.st==='refuse'&&!o.arrived).forEach(o=>AL.push(['w',`Отказ ${o.id} — товар в пути назад`,`${esc(o.why||'')} · резерв держится до приёмки`,`openOrd('${o.id}')`]));
 PRODUCTS.forEach(p=>SK.filter(inStore).forEach(s=>{if(freeQ(p.id,s)<p.min&&freeQ(p.id,s)<=p.min/3)AL.push(['w',`${esc(p.n)} — ${freeQ(p.id,s)} уп. на ${STORES[s].s}`,`Минимум ${p.min}. ${MOVES.some(m=>m.st==='way'&&m.to===s&&m.lines.some(l=>l[0]===p.id))?'Перемещение уже в пути':'Заказать у поставщика или переместить'}`,`card('pr','${p.id}')`])}));
 if(INT('ismp').st==='err')AL.push(['r','ИС МПТ: 1 код БАД не найден','Накладная ВМ-Н-2207 «Витамакс» — запрос поставщику отправлен',`card('int','ismp')`]);
 BATCHES.filter(b=>inStore(b.s)&&b.q>0&&daysBetween(TODAY,b.exp)<=45).forEach(b=>AL.push(['w',`Срок: ${esc(PR(b.p).n)}`,`Партия ${b.no} · ${b.q} уп. на ${STORES[b.s].s} · годен до ${dl(b.exp)}`,`go('batches')`]));
 CONTRACTS.filter(c=>daysBetween(TODAY,c.to)<=30).forEach(c=>AL.push(['i',`Договор ${c.no} истекает ${dl(c.to)}`,`${esc(SU(c.sup).n)} — продлить или подписать ДС`,`card('ctr','${c.id}')`]));
 PRODUCTS.filter(p=>p.nkt!=='ok'&&p.mpl.length).forEach(p=>AL.push(['i',`НКТ: карточка «${esc(p.n)}» на модерации`,'Пока на площадках не публикуется',`go('nkt')`]));
 return `<div class="hd"><div><h2>Пульт дня · 1 октября, ${NOW}</h2><p>${store==='all'?'Обе аптеки':stName(store)+' · '+STORES[store].addr}. Все заказы Kaspi, Halyk и Forte попадают сюда сами — вводить номер, товар и сумму вручную больше не нужно.</p></div><div class="btns"><button class="bt" onclick="go('analytics')">Аналитика</button><button class="bt p" onclick="go('orders')">Лента заказов</button></div></div>
 <div class="route">${lanes.map(l=>`<div class="rt rt-${l.s.k}" style="--c:${l.s.c}" onclick="ordF='${l.s.k}';go('orders')"><small>${esc(l.s.n)}</small><b>${l.n}</b><span>${esc(l.s.d)}</span></div>`).join('')}</div>
 <div class="g21"><div class="pan"><h3>Требует действия · ${AL.length}</h3><p>Система сама собирает то, что раньше держалось в голове: новые заказы, отказы, минимальные остатки, сроки, ошибки маркировки, договоры.</p>${AL.slice(0,9).map(a=>`<div class="al ${a[0]}" onclick="${a[3]}"><b>${a[1]}</b><span>${a[2]}</span></div>`).join('')}</div>
 <div><div class="pan"><h3>Выручка сегодня · ${tg(tot)}</h3><p>Только по фискальным чекам — заказ в пути выручкой не считается.</p><div class="tw"><table class="t"><thead><tr><th>Канал</th>${SK.filter(inStore).map(s=>`<th class="r">${STORES[s].s}</th>`).join('')}<th class="r">Итого</th></tr></thead><tbody>${Object.keys(MP).map(k=>`<tr onclick="go('checks')"><td>${mpm(k)} ${esc(MP[k].n)}</td>${SK.filter(inStore).map(s=>`<td class="r mono">${fmt(rev[k][s])}</td>`).join('')}<td class="r mono"><b>${fmt(rev[k].A1+rev[k].A2)}</b></td></tr>`).join('')}</tbody></table></div>
  <div class="kv" style="margin-top:8px"><span>Фискальных чеков сегодня</span><b>${ch.length}</b></div><div class="kv"><span>Открытых товарных чеков (резерв, сборка, доставка)</span><b>${O.filter(o=>RES_ST.includes(o.st)).length}</b></div><div class="kv"><span>Товар в резерве, по продажной цене</span><b>${tg(O.filter(o=>RES_ST.includes(o.st)).reduce((a,o)=>a+oSum(o),0))}</b></div></div>
 <div class="pan"><h3>Интеграции</h3>${INTEG.map(i=>`<div class="kv" style="cursor:pointer" onclick="card('int','${i.k}')"><span><i class="dot ${i.st}"></i>${esc(i.full)}</span><b class="mono">${esc(i.ago)}</b></div>`).join('')}</div></div></div>
 ${said('«Заказ выпал — мне надо у себя в программе сделать реализацию: ввести номер заказа, наименование товара, сумму, откуда упал заказ, в какой магазин… А заказ в пути — клиент может отказать, а я уже пробил фискальный чек.»','Теперь: заказ приходит сам, до выдачи — только резерв и товарный чек, фискальный чек — автоматически по статусу «выдан».')}`};

/* ===== Аналитика ===== */
const MONTH={kaspi:{A1:[4210000,312,11],A2:[2940000,228,9]},halyk:{A1:[910000,74,6],A2:[620000,51,4]},forte:{A1:[380000,33,5],A2:[290000,24,3]},shop:{A1:[6820000,2140,0],A2:[5130000,1720,0]}};
const MONTH_PREV={kaspi:3720000,halyk:780000,forte:410000,shop:11400000};
SC.analytics=()=>{const S=SK.filter(inStore);const sum=k=>S.reduce((a,s)=>a+MONTH[k][s][0],0),cnt2=k=>S.reduce((a,s)=>a+MONTH[k][s][1],0),ref=k=>S.reduce((a,s)=>a+MONTH[k][s][2],0);
 const tot=Object.keys(MP).reduce((a,k)=>a+sum(k),0),mx=Math.max(...Object.keys(MP).map(sum));
 const top=[['P07',96,315840],['P09',61,365390],['P01',388,112520],['P12',14,250600],['P04',118,116820],['P08',41,188190],['P16',57,136230]];
 const marg=p=>pct(PR(p).price-PR(p).cost,PR(p).price);
 const prev=Object.keys(MP).reduce((a,k)=>a+MONTH_PREV[k],0)*(S.length/2),grow=pct(tot-prev,prev);
 return `<div class="hd"><div><h2>Аналитика · сентябрь 2026</h2><p>${store==='all'?'Обе аптеки':stName(store)}. Продажи по каналам и аптекам, отказы по площадкам, маржа по товарам, остатки без движения. Любой показатель, который захотите — добавим.</p></div><div class="btns"><button class="bt" onclick="act('report')">Отчёт в WhatsApp каждый вечер</button></div></div>
 <div class="wid"><div><small>Выручка за месяц</small><b class="a">${mln(tot)}</b><span>${grow>0?'+':''}${grow}% к августу</span></div><div><small>Доля площадок</small><b>${pct(tot-sum('shop'),tot)}%</b><span>Kaspi + Halyk + Forte</span></div><div><small>Заказов с площадок</small><b>${fmt(cnt2('kaspi')+cnt2('halyk')+cnt2('forte'))}</b><span>отказов ${ref('kaspi')+ref('halyk')+ref('forte')}</span></div><div><small>Средний чек в аптеке</small><b>${tg(sum('shop')/cnt2('shop'))}</b><span>${fmt(cnt2('shop'))} чеков</span></div><div><small>Валовая маржа</small><b class="g">36%</b><span>по себестоимости партий</span></div></div>
 <div class="g2"><div class="pan"><h3>Выручка по каналам</h3><p>Сентябрь, по фискальным чекам.</p>${Object.keys(MP).map(k=>`<div class="fr"><span>${mpm(k)} ${esc(MP[k].n)}</span><div class="bar"><i style="--w:${pct(sum(k),mx)}%;background:${MP[k].c}"></i></div><b>${mln(sum(k))} · ${pct(sum(k),tot)}%</b></div>`).join('')}
  <div class="tw" style="margin-top:12px"><table class="t"><thead><tr><th>Канал</th>${S.map(s=>`<th class="r">${STORES[s].s}</th>`).join('')}<th class="r">Заказов</th><th class="r">Отказы</th></tr></thead><tbody>${Object.keys(MP).map(k=>`<tr><td>${esc(MP[k].s)}</td>${S.map(s=>`<td class="r mono">${fmt(MONTH[k][s][0])}</td>`).join('')}<td class="r mono">${fmt(cnt2(k))}</td><td class="r mono">${k==='shop'?'—':ref(k)+' · '+(Math.round(ref(k)/cnt2(k)*1000)/10).toString().replace('.',',')+'%'}</td></tr>`).join('')}</tbody></table></div></div>
 <div class="pan"><h3>Топ товаров площадок</h3><p>Сколько продано, на какую сумму и какая маржа.</p><div class="tw"><table class="t"><thead><tr><th>Товар</th><th class="r">Шт.</th><th class="r">Сумма</th><th class="r">Маржа</th></tr></thead><tbody>${top.map(t=>`<tr onclick="card('pr','${t[0]}')"><td>${esc(PR(t[0]).n)}</td><td class="r mono">${t[1]}</td><td class="r mono">${fmt(t[2])}</td><td class="r mono">${marg(t[0])}%</td></tr>`).join('')}</tbody></table></div>
  <div class="note" style="--tone:var(--warn)"><b>Без движения 60+ дней</b><p>Крем детский 75 мл — 10 шт. на 9 800 ₸ себестоимости; пластырь №20 на №2 — 16 шт. Предложение: переместить или выставить на Kaspi.</p></div></div></div>
 <div class="pan"><h3>Отказы по площадкам и причинам</h3><p>Каждый отказ — это товар, который сутки-двое был в резерве и не продавался. Видно, где их больше.</p><div class="g3" style="margin:0">${[['Клиент не отвечал',9,'kaspi'],['Передумал при получении',7,'forte'],['Неверный адрес',6,'kaspi'],['Долгая доставка',5,'halyk'],['Нашёл дешевле',4,'kaspi'],['Прочее',7,'halyk']].map(r=>`<div class="kv"><span>${r[0]}</span><b class="mono">${r[1]}</b></div>`).join('')}</div></div>`};

/* ===== Лента заказов ===== */
let ordF='all',ordMp='all',ordView='board';
const nextBtn=o=>({new:'В резерв',res:'Собран',pack:isPickup(o)?'Выдать':'Курьеру',courier:'Выдан'}[o.st]);
const actBtns=(o,sm)=>`${nextBtn(o)?`<button class="bt ${sm?'sm':''} p" onclick="event.stopPropagation();ordAdv('${o.id}')">${nextBtn(o)}</button>`:''}${o.st==='refuse'?`<button class="bt ${sm?'sm':''} r" onclick="event.stopPropagation();ordBack('${o.id}')">Товар вернулся</button>`:''}${['new','res','pack','courier'].includes(o.st)?`<button class="bt ${sm?'sm':''}" onclick="event.stopPropagation();ordRefuse('${o.id}')">${o.st==='courier'?'Отказ':'Отмена'}</button>`:''}`;
SC.orders=()=>{const O=SO().filter(o=>(ordMp==='all'||o.mp===ordMp));const F=O.filter(o=>ordF==='all'||o.st===ordF);
 return `<div class="hd"><div><h2>Лента заказов</h2><p>Kaspi, Halyk и Forte в одной очереди: номер, дата, клиент, телефон, состав, аптека. Резерв — сразу; товарный чек — при резерве; фискальный — только когда площадка пришлёт «выдан» или клиент забрал в аптеке.</p></div><div class="btns"><div class="seg"><button class="${ordView==='board'?'on':''}" onclick="ordView='board';render()">Доска</button><button class="${ordView==='list'?'on':''}" onclick="ordView='list';render()">Список</button></div></div></div>
 <div class="filt"><button class="${ordMp==='all'?'on':''}" onclick="ordMp='all';render()">Все площадки · ${SO().length}</button>${['kaspi','halyk','forte'].map(k=>`<button class="${ordMp===k?'on':''}" onclick="ordMp='${k}';render()"><i class="sq" style="background:${MP[k].c}"></i>${MP[k].s} · ${SO().filter(o=>o.mp===k).length}</button>`).join('')}<span class="fsep"></span>${ordView==='list'?`<button class="${ordF==='all'?'on':''}" onclick="ordF='all';render()">Все статусы</button>${OST.map(s=>`<button class="${ordF===s.k?'on':''}" onclick="ordF='${s.k}';render()">${s.n} · ${O.filter(o=>o.st===s.k).length}</button>`).join('')}`:''}</div>
 ${ordView==='board'?`<div class="board">${OST.map(s=>{const L=O.filter(o=>o.st===s.k);return `<div class="bcol ${ordF===s.k?'hl':''}"><div class="bh" style="--c:${s.c}"><b>${s.n}</b><span>${L.length} · ${fmt(L.reduce((a,o)=>a+oSum(o),0))} ₸</span></div>${L.map(o=>`<div class="oc" onclick="openOrd('${o.id}')"><div class="ocb">${mpm(o.mp)}<span class="mono">${esc(o.id)}</span>${stm(o.s)}</div><b>${esc(o.cl)}</b><span>${o.it.map(i=>esc(PR(i[0]).n.split(',')[0])+' × '+i[1]).join('; ')}</span><div class="ocf"><strong>${tg(oSum(o))}</strong><em>${dd(o.d)} ${o.t}</em></div>${o.st==='refuse'?`<div class="ocw">${o.arrived?'Товар привезли — подтвердите':'Везут назад'}</div>`:''}<div class="ocbtn">${actBtns(o,1)}</div></div>`).join('')||'<div class="kempty">—</div>'}</div>`}).join('')}</div>`
 :`<div class="tw"><table class="t"><thead><tr><th>Заказ</th><th>Площадка</th><th>Пришёл</th><th>Клиент</th><th>Состав</th><th>Аптека</th><th class="r">Сумма</th><th>Статус</th><th>Документ</th><th></th></tr></thead><tbody>${F.map(o=>`<tr onclick="openOrd('${o.id}')"><td class="mono">${esc(o.id)}</td><td>${mpm(o.mp)}</td><td class="mono">${dd(o.d)} ${o.t}</td><td>${esc(o.cl)}<span class="sub mono">${esc(o.ph)}</span></td><td>${o.it.map(i=>esc(PR(i[0]).n.split(',')[0])+' × '+i[1]).join('<br>')}</td><td>${stm(o.s)}</td><td class="r mono">${fmt(oSum(o))}</td><td>${ost(o.st)}</td><td class="mono">${o.fc?'<span class="pos">'+o.fc+'</span>':o.tc?o.tc:'—'}</td><td><div class="rbtn">${actBtns(o,1)}</div></td></tr>`).join('')}</tbody></table></div>`}
 <div class="note"><b>Почему чек не пробивается сразу</b><p>Пока заказ у курьера, клиент может отказаться. Раньше чек был уже пробит — приходилось оформлять возврат по чеку. Теперь до выдачи есть только товарный чек, а фискальный создаётся автоматически по статусу «выдан» от площадки.</p></div>`};

/* ===== Карточка заказа ===== */
function openOrd(id){if(!OR(id))return;curOrd=id;if(allowed('order')&&cur!=='order'){go('order')}else if(allowed('order')){render()}else card('ord',id)}
const FLOW=['new','res','pack','courier','done'];
const ordSteps=o=>{const i=o.st==='refuse'||o.st==='back'?3:FLOW.indexOf(o.st);return `<div class="steps">${FLOW.map((k,j)=>`<div class="stp ${j<i||o.st==='done'&&j===i?'done':j===i&&o.st!=='refuse'&&o.st!=='back'?'on':''}"><i>${j+1}</i>${esc(OSTOF(k).n)}</div>`).join('')}${o.st==='refuse'||o.st==='back'?`<div class="stp ${o.st==='refuse'?'on bad':'done'}"><i>↩</i>${esc(OSTOF(o.st).n)}</div>`:''}</div>`};
const ordBody=o=>`${ordSteps(o)}
 <div class="g21"><div><div class="pan"><h3>Состав заказа</h3><div class="tw"><table class="t"><thead><tr><th>Товар</th><th class="r">Кол-во</th><th class="r">Свободно на ${STORES[o.s].s}</th><th class="r">Цена</th><th class="r">Сумма</th><th>НДС</th><th>Маркировка</th></tr></thead><tbody>${o.it.map(i=>{const p=PR(i[0]);return `<tr onclick="card('pr','${p.id}')"><td>${esc(p.n)}${p.rx?' <span class="rx">Rx</span>':''}</td><td class="r mono">${i[1]}</td><td class="r mono">${freeQ(p.id,o.s)}</td><td class="r mono">${fmt(p.price)}</td><td class="r mono">${fmt(lineSum(i))}</td><td class="mono">${vatOf(p)}%</td><td>${p.mk?(o.st==='done'?'<span class="pos">выведен из оборота</span>':'в обороте'):'<span class="mini">не нужна</span>'}</td></tr>`}).join('')}<tr class="total"><td>Итого</td><td class="r mono">${oQty(o)}</td><td></td><td></td><td class="r mono">${fmt(oSum(o))}</td><td colspan="2" class="mini">${vatLine(o.it)}</td></tr></tbody></table></div>
  <div class="btns l" style="margin-top:12px">${actBtns(o)}<button class="bt" onclick="card('tch','${o.id}')">Товарный чек</button>${o.fc?`<button class="bt g" onclick="card('chk','${o.fc}')">Фискальный чек ${o.fc}</button>`:''}<button class="bt" onclick="act('wa')">Написать клиенту</button></div></div>
 <div class="pan"><h3>Документы заказа</h3>
  <div class="doclane"><div class="${o.tc?'ok':''}"><small>1 · при резерве</small><b>Товарный чек</b><span class="mono">${o.tc||'появится при резерве'}</span></div><div class="${o.fc?'ok':o.st==='back'?'no':''}"><small>2 · при «выдан»</small><b>Фискальный чек → ОФД</b><span class="mono">${o.fc||(o.st==='back'?'не пробивался — не нужен':'ждёт статуса «выдан»')}</span></div><div class="${o.fc&&o.it.some(i=>PR(i[0]).mk)?'ok':o.st==='back'?'no':''}"><small>3 · вместе с чеком</small><b>ИС МПТ: выбытие кодов</b><span>${o.it.some(i=>PR(i[0]).mk)?(o.fc?'коды выведены из оборота':o.st==='back'?'коды остались в обороте':'после выдачи'):'товар без маркировки'}</span></div></div></div></div>
 <div><div class="pan"><h3>Клиент и доставка</h3>${[['Клиент',esc(o.cl)],['Телефон',`<span class="mono">${esc(o.ph)}</span>`],['Площадка',MP[o.mp].n],['Номер на площадке',`<span class="mono">${esc(o.id)}</span>`],['Пришёл',dl(o.d)+' '+o.t],['Аптека',stName(o.s)+' · '+STORES[o.s].addr],['Доставка',esc(o.dlv)]].concat(o.why?[['Причина отказа',esc(o.why)]]:[]).map(x=>`<div class="kv"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div>
 <div class="pan"><h3>История</h3><div class="tl">${o.h.slice().reverse().map((x,j)=>`<div class="tli ${j===0?'on':'ok'}"><span class="who">${esc(x[0])}</span><b>${esc(x[1])}</b></div>`).join('')}</div></div></div></div>`;
SC.order=()=>{const o=OR(curOrd)||ORDERS[0];const L=SO();
 return `<div class="crumb"><a onclick="go('orders')">Лента заказов</a> / ${esc(MP[o.mp].n)} / ${esc(o.id)}</div>
 <div class="hd"><div><h2>${mpm(o.mp)} Заказ ${esc(o.id)} · ${ost(o.st)}</h2><p>${esc(o.cl)} · ${oQty(o)} шт. · ${tg(oSum(o))} · ${stName(o.s)}. ${esc(OSTOF(o.st).d)}</p></div><div class="btns"><select class="osel" onchange="curOrd=this.value;render()">${L.map(x=>`<option value="${x.id}" ${x.id===o.id?'selected':''}>${x.id} · ${OSTOF(x.st).n}</option>`).join('')}</select></div></div>
 ${ordBody(o)}
 ${said('«Чтобы товар, когда заказ поступил, упаковали, передали в службу доставки, и после того как выдано будет — чтобы у меня автоматически пробивался чек. До этого момента — только товарный чек.»')}`};

/* ===== Отказы и возвраты ===== */
SC.returns=()=>{const R=SO().filter(o=>o.st==='refuse'),B=SO().filter(o=>o.st==='back');
 return `<div class="hd"><div><h2>Отказы и возвраты</h2><p>Отказ от площадки ставит заказ в «везут назад» — товар числится в резерве, на площадках не продаётся. Когда курьер привёз — сотрудник жмёт «Товар вернулся»: резерв снимается, остаток восстанавливается на той аптеке, откуда уходил.</p></div></div>
 <div class="flow3"><div><small>1</small><b>Площадка: отказ</b><span>Kaspi, Halyk или Forte присылают статус сами</span></div><div><small>2</small><b>Товар в пути назад</b><span>резерв держится, чек не пробит</span></div><div><small>3</small><b>«Товар вернулся»</b><span>одна кнопка в аптеке или в телефоне</span></div><div class="ok"><small>4</small><b>Снова в продаже</b><span>остаток +N на нужной аптеке и на всех площадках</span></div></div>
 <div class="pan"><h3>Ждут приёмки · ${R.length}</h3>${R.length?`<div class="tw"><table class="t"><thead><tr><th>Заказ</th><th>Площадка</th><th>Клиент</th><th>Товар</th><th>Аптека</th><th>Причина</th><th>Где товар</th><th></th></tr></thead><tbody>${R.map(o=>`<tr onclick="openOrd('${o.id}')"><td class="mono">${esc(o.id)}</td><td>${mpm(o.mp)}</td><td>${esc(o.cl)}</td><td>${o.it.map(i=>esc(PR(i[0]).n.split(',')[0])+' × '+i[1]).join('<br>')}</td><td>${stm(o.s)}</td><td>${esc(o.why||'—')}</td><td>${o.arrived?'<b class="warnt">привезли в аптеку</b>':'у курьера'}</td><td><button class="bt sm r" onclick="event.stopPropagation();ordBack('${o.id}')">Товар вернулся</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="mini">Все возвраты приняты.</p>'}</div>
 <div class="g2"><div class="pan"><h3>Принятые возвраты</h3>${B.map(o=>`<div class="kv" style="cursor:pointer" onclick="openOrd('${o.id}')"><span>${mpm(o.mp)} <span class="mono">${esc(o.id)}</span> · ${esc(o.why||'')}</span><b>${tg(oSum(o))}</b></div>`).join('')||'<p class="mini">Пока нет.</p>'}</div>
 <div class="pan"><h3>Сентябрь</h3>${[['Отказов с площадок',38],['Возвратов по фискальному чеку','0'],['Раньше — возвратов по чеку в месяц','≈ 30–40'],['Средний срок возврата товара','1,6 дня']].map(x=>`<div class="kv"><span>${x[0]}</span><b class="mono">${x[1]}</b></div>`).join('')}<p class="mini" style="margin-top:8px">Если клиент вернул товар уже после выдачи — это обычный возврат по чеку, система оформит его по ОФД и вернёт коды в оборот.</p></div></div>
 ${said('«Возврат — как мы получим от курьерской службы, и мы у себя подтвердили, что товар мы получили, — убрать резерв и перекинуть на склад.»')}`};

/* ===== Чеки и ОФД ===== */
let chkTab='f';
SC.checks=()=>{const C=CHECKS.filter(c=>inStore(c.s)),T=TCHECKS.filter(t=>inStore(t.s));
 const z=s=>{const L=CHECKS.filter(c=>c.s===s);const v={};L.forEach(c=>{const r=vatSplit(c.it);Object.keys(r).forEach(k=>v[k]=(v[k]||0)+r[k])});return [L.length,L.reduce((a,c)=>a+cSum(c),0),v]};
 return `<div class="hd"><div><h2>Чеки и ОФД</h2><p>Два вида документов. Товарный чек — внутренний, печатается при резерве и кладётся в пакет. Фискальный — уходит в ОФД только при фактической выдаче или продаже в аптеке, с разбивкой НДС 5% и 16%.</p></div><div class="btns"><button class="bt" onclick="act('z')">Z-отчёт смены</button></div></div>
 <div class="g2">${SK.filter(inStore).map(s=>{const [n,sm,v]=z(s);return `<div class="pan zr"><h3>${stName(s)} · ${STORES[s].kkm}</h3>${[['Чеков за смену',n],['Сумма',tg(sm)]].concat(Object.keys(v).sort((a,b)=>a-b).map(k=>['в т. ч. НДС '+k+'%',tg(vatSum(v[k],+k))])).map(x=>`<div class="kv"><span>${x[0]}</span><b class="mono">${x[1]}</b></div>`).join('')}</div>`}).join('')}</div>
 <div class="tabs"><a class="tab ${chkTab==='f'?'on':''}" onclick="chkTab='f';render()">Фискальные чеки · ${C.length}</a><a class="tab ${chkTab==='t'?'on':''}" onclick="chkTab='t';render()">Товарные чеки · ${T.length}</a></div>
 ${chkTab==='f'?`<div class="tw"><table class="t"><thead><tr><th>Чек</th><th>Время</th><th>Аптека</th><th>Источник</th><th>Заказ</th><th class="r">Сумма</th><th>НДС</th><th>Оплата</th><th>ОФД</th></tr></thead><tbody>${C.map(c=>`<tr onclick="card('chk','${c.no}')"><td class="mono">${c.no}</td><td class="mono">${c.t}</td><td>${stm(c.s)}</td><td>${mpm(c.src)}</td><td>${c.ord?ordL(c.ord):'<span class="mini">в аптеке</span>'}</td><td class="r mono">${fmt(cSum(c))}</td><td class="mini">${vatLine(c.it)}</td><td>${esc(c.pay)}</td><td>${c.ofd==='ok'?'<span class="pos">принят</span>':'<span class="warnt">отправляется</span>'}</td></tr>`).join('')}</tbody></table></div>`
 :`<div class="tw"><table class="t"><thead><tr><th>Товарный чек</th><th>Заказ</th><th>Аптека</th><th>Статус заказа</th><th>Что дальше</th></tr></thead><tbody>${T.map(t=>`<tr onclick="openOrd('${t.ord}')"><td class="mono">${t.no}</td><td class="mono">${t.ord}</td><td>${stm(t.s)}</td><td>${ost(t.st)}</td><td class="mini">${t.st==='done'?'закрыт фискальным чеком':t.st==='back'?'аннулирован: возврат, фискальный не нужен':'ждёт выдачи'}</td></tr>`).join('')}</tbody></table></div>`}
 ${said('«После того как выдано будет клиенту — пробивался фискальный чек. До этого момента — только товарный чек.»')}`};

/* ===== Продажа в аптеке ===== */
let CART=[],posStore='A1',posFound='';
function posStoreNow(){return ROLES[role].st||(store==='all'?posStore:store)}
function findBc(code){const q=String(code).trim().toLowerCase();for(const p of PRODUCTS){const b=p.bc.find(x=>x[0].toLowerCase()===q);if(b)return [p,b]}return null}
function posScan(code){const r=findBc(code);if(!r){toast('Код не найден. Можно добавить его к нужному товару — у товара может быть сколько угодно штрихкодов и артикулов.');return}const [p,b]=r;posFound=`${esc(p.n)} — найден по коду <span class="mono">${esc(b[0])}</span> (${esc(b[1])})`;const e=CART.find(c=>c[0]===p.id&&c[2]!=='u');if(e)e[1]++;else CART.push([p.id,1]);render()}
function posUnit(i){const c=CART[i],p=PR(c[0]);if(!p.u){toast('Этот товар не делится — продаётся только целой упаковкой.');return}c[2]=c[2]==='u'?undefined:'u';render()}
function posPay(how){if(!CART.length){toast('Корзина пустая — отсканируйте товар.');return}const s=posStoreNow();let opened=[];
 CART.forEach(c=>{const p=PR(c[0]);if(c[2]==='u'){let need=c[1];while(p.op[s]<need){p.st[s][0]--;fefoTake(p.id,s,1);p.op[s]+=p.u[1];opened.push(p.n.split(',')[0])}p.op[s]-=need}else{p.st[s][0]-=c[1];fefoTake(p.id,s,c[1])}});
 const no=`ФЧ-${s[1]}-0${fcN[s]++}`;CHECKS.unshift({no,s,t:NOW,src:'shop',it:CART.map(c=>c.slice()),pay:how,ofd:'ok'});const sm=CART.reduce((a,c)=>a+lineSum(c),0),vl=vatLine(CART);CART=[];posFound='';render();
 toast(`Чек <b>${no}</b> на ${tg(sm)} ушёл в ОФД (${vl}).${opened.length?' Вскрыта упаковка: '+esc(opened.join(', '))+' — остаток пересчитан в блистеры.':''}`)}
SC.pos=()=>{const s=posStoreNow();const sm=CART.reduce((a,c)=>a+lineSum(c),0);
 return `<div class="hd"><div><h2>Продажа в аптеке · ${stName(s)}</h2><p>Сканер читает любой из штрихкодов товара — заводской, старой упаковки, артикул поставщика. Можно продать целую упаковку или один блистер: упаковка вскрывается автоматически, остаток считается в блистерах.</p></div>${ROLES[role].st||store!=='all'?'':`<div class="btns"><div class="seg">${SK.map(k=>`<button class="${posStore===k?'on':''}" onclick="posStore='${k}';render()">${STORES[k].s}</button>`).join('')}</div></div>`}</div>
 <div class="g12"><div class="pan"><h3>Сканер</h3><div class="scan"><input id="bcin" placeholder="штрихкод или артикул" onkeydown="if(event.key==='Enter'){posScan(this.value);this.value=''}"><button class="bt p" onclick="const i=document.getElementById('bcin');posScan(i.value);i.value=''">Найти</button></div>
  <p class="mini" style="margin:10px 0 6px">Попробуйте коды одного и того же парацетамола:</p><div class="codes">${PR('P01').bc.slice(0,4).map(b=>`<button onclick="posScan('${b[0]}')"><span class="mono">${b[0]}</span><small>${esc(b[1])}</small></button>`).join('')}<button onclick="posScan('3582910065312')"><span class="mono">3582910065312</span><small>Магний B6</small></button><button onclick="posScan('VM-OM3-90')"><span class="mono">VM-OM3-90</span><small>Омега-3 · БАД</small></button></div>
  ${posFound?`<div class="note" style="--tone:var(--ok)"><b>Найдено</b><p>${posFound}</p></div>`:''}</div>
 <div class="pan"><h3>Чек</h3>${CART.length?`<div class="tw"><table class="t"><thead><tr><th>Товар</th><th>Единица</th><th class="r">Кол-во</th><th class="r">Цена</th><th class="r">Сумма</th><th>НДС</th><th></th></tr></thead><tbody>${CART.map((c,i)=>{const p=PR(c[0]);return `<tr><td>${esc(p.n)}${p.mk?' <span class="mkm">DataMatrix</span>':''}</td><td>${p.u?`<div class="seg sm"><button class="${c[2]!=='u'?'on':''}" onclick="if(CART[${i}][2]==='u')posUnit(${i})">упаковка</button><button class="${c[2]==='u'?'on':''}" onclick="if(CART[${i}][2]!=='u')posUnit(${i})">${p.u[0]}</button></div>`:'<span class="mini">упаковка</span>'}</td><td class="r"><input class="qin" value="${c[1]}" onchange="CART[${i}][1]=Math.max(1,+this.value||1);render()"></td><td class="r mono">${fmt(c[2]==='u'?p.u[2]:p.price)}</td><td class="r mono">${fmt(lineSum(c))}</td><td class="mono">${vatOf(p)}%</td><td><a class="lk" onclick="CART.splice(${i},1);render()">убрать</a></td></tr>`}).join('')}<tr class="total"><td colspan="4">Итого · ${vatLine(CART)}</td><td class="r mono">${fmt(sm)}</td><td colspan="2"></td></tr></tbody></table></div>
  <div class="btns l" style="margin-top:12px">${['Наличные','Карта','Kaspi QR'].map(h=>`<button class="bt p" onclick="posPay('${h}')">${h}</button>`).join('')}<button class="bt" onclick="CART=[];posFound='';render()">Очистить</button></div>`:'<p class="mini">Отсканируйте товар или нажмите один из кодов слева.</p>'}
  <div class="opn"><small>Вскрытые упаковки на ${STORES[s].s}</small>${PRODUCTS.filter(p=>p.u&&p.op[s]).map(p=>`<span>${esc(p.n.split(',')[0])} <b class="mono">${p.op[s]} ${esc(p.u[0])}</b></span>`).join('')||'<span>—</span>'}</div></div></div>
 ${said('«Отдельно название товара плюс штрихкод… возможность этому товару добавить несколько артикулов — не один, а сразу пять, шесть, сколько получится.»')}`};

/* ===== WhatsApp и Telegram ===== */
let curChat='W1';
SC.chats=()=>{const c=CHATS.find(x=>x.id===curChat)||CHATS[0];c.un=0;
 return `<div class="hd"><div><h2>WhatsApp и Telegram</h2><p>Переписка с поставщиками и клиентами — в системе, рядом с заказом или накладной. Шаблоны «заказ собран», «передан курьеру», «напоминание о продлении договора» отправляются в один клик. Телефония не нужна — как вы сказали.</p></div></div>
 <div class="chw"><div class="chl">${CHATS.map(x=>`<div class="chi ${x.id===c.id?'on':''}" onclick="curChat='${x.id}';render()"><i class="chn ${x.ch}">${x.ch==='wa'?'WA':'TG'}</i><div><b>${esc(x.n)}</b><span>${esc(x.sub)}</span></div>${x.un?`<em>${x.un}</em>`:''}</div>`).join('')}</div>
 <div class="chm"><div class="chh"><b>${esc(c.n)}</b><span>${c.ch==='wa'?'WhatsApp':'Telegram'} · ${esc(c.sub)}</span></div><div class="chat">${c.ms.map(m=>`<div class="msg ${m[0]}">${esc(m[1])}<small>${esc(m[2])}</small></div>`).join('')}</div>
  <div class="chs"><input id="chin" placeholder="Сообщение…" onkeydown="if(event.key==='Enter')chatSend()"><button class="bt p" onclick="chatSend()">Отправить</button></div>
  <div class="tpls">${['Ваш заказ собран и ждёт курьера','Заказ передан курьеру, ожидайте сегодня','Пришлите, пожалуйста, скан накладной в PDF','Договор истекает — нужен ДС о продлении'].map(t=>`<button onclick="document.getElementById('chin').value='${t}'">${t}</button>`).join('')}</div></div></div>`};
function chatSend(){const i=document.getElementById('chin');if(!i||!i.value.trim())return;const c=CHATS.find(x=>x.id===curChat);c.ms.push(['out',i.value.trim(),NOW]);render();toast(`Отправлено в ${c.ch==='wa'?'WhatsApp':'Telegram'}.`)}

/* ===== Площадки: витрины и остатки ===== */
const mpPrice=(p,k)=>k==='kaspi'?((DUMP.find(d=>d.p===p.id)||{}).our||p.price):p.price;
SC.market=()=>{const L=PRODUCTS.filter(p=>p.mpl.length||p.nkt!=='ok');
 return `<div class="hd"><div><h2>Витрины площадок и остатки</h2><p>Каждые несколько минут система отправляет на Kaspi, Halyk и Forte цену и <b>свободный</b> остаток по каждой аптеке — уже за вычетом резерва. Продать то, что лежит в чужом заказе, нельзя.</p></div><div class="btns"><button class="bt" onclick="act('sync')">Обновить сейчас</button></div></div>
 <div class="g3">${['kaspi','halyk','forte'].map(k=>{const i=INT(k);const pub=PRODUCTS.filter(p=>p.mpl.includes(k));return `<div class="pan mpp" style="--c:${MP[k].c}"><h3>${esc(MP[k].n)}</h3>${[['Связь',`<i class="dot ${i.st}"></i>${esc(i.ago)} назад`],['Товаров на витрине',pub.length],['Заказов сегодня',ORDERS.filter(o=>o.mp===k&&o.d===TODAY).length],['Точки выдачи',k==='kaspi'?'PP1 — №1, PP2 — №2':'обе аптеки'],['Не опубликовано (нет НКТ)',PRODUCTS.filter(p=>p.nkt!=='ok'&&p.mpl.includes(k)).length]].map(x=>`<div class="kv"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}${i.msg?`<div class="note" style="--tone:var(--warn)"><p>${esc(i.msg)}</p></div>`:''}</div>`}).join('')}</div>
 <div class="tw"><table class="t"><thead><tr><th>Товар</th><th>НКТ</th><th class="r">Свободно №1</th><th class="r">Свободно №2</th>${['kaspi','halyk','forte'].map(k=>`<th class="r">${MP[k].s}</th>`).join('')}</tr></thead><tbody>${L.map(p=>`<tr onclick="card('pr','${p.id}')"><td>${esc(p.n)}</td><td>${p.nkt==='ok'?'<span class="pos">есть</span>':p.nkt==='wait'?'<span class="warnt">модерация</span>':'<span class="neg">нет</span>'}</td>${SK.map(s=>`<td class="r mono ${freeQ(p.id,s)<p.min?'warnt':''}">${freeQ(p.id,s)}</td>`).join('')}${['kaspi','halyk','forte'].map(k=>`<td class="r mono">${p.mpl.includes(k)?(p.nkt==='ok'?fmt(mpPrice(p,k)):'<span class="warnt">ждёт НКТ</span>'):'<span class="mini">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>
 ${said('«В данный момент у меня подключено — передаю только остатки и цены, и в каком магазине есть товар в наличии. Ещё мне хотелось бы более автоматизировать.»','Остатки и цены остаются, к ним добавляются заказы, резерв, статусы «выдан» и «отказ».')}`};

/* ===== Демпинг Kaspi ===== */
SC.dumping=()=>`<div class="hd"><div><h2>Цены и демпинг на Kaspi</h2><p>Робот каждые 15 минут смотрит минимальную цену конкурентов по каждой карточке и снижает вашу цену на шаг — но никогда не ниже порога. Порог считается от себестоимости партии, чтобы не продавать в минус.</p></div><div class="btns"><button class="bt" onclick="act('floor')">Порог: себестоимость + 15%</button></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Товар</th><th class="r">Наша цена</th><th class="r">Мин. у конкурентов</th><th class="r">Место</th><th class="r">Продавцов</th><th class="r">Порог</th><th class="r">Шаг</th><th class="r">Маржа на пороге</th><th>Робот</th></tr></thead><tbody>${DUMP.map((d,i)=>{const p=PR(d.p);return `<tr onclick="card('pr','${p.id}')"><td>${esc(p.n)}</td><td class="r mono"><b>${fmt(d.our)}</b></td><td class="r mono ${d.comp<d.our?'neg':'pos'}">${fmt(d.comp)}</td><td class="r mono">${d.pos}</td><td class="r mono">${d.sellers}</td><td class="r mono">${fmt(d.floor)}</td><td class="r mono">${d.step}</td><td class="r mono">${pct(d.floor-p.cost,d.floor)}%</td><td onclick="event.stopPropagation()"><span class="sw ${d.auto?'on':''}" onclick="DUMP[${i}].auto=!DUMP[${i}].auto;render();toast(DUMP[${i}].auto?'Робот включён для этой карточки.':'Робот выключен — цена не меняется.')"></span></td></tr>`}).join('')}</tbody></table></div>
 <div class="g2" style="margin-top:12px"><div class="pan"><h3>Журнал робота · сегодня</h3>${DLOG.map(l=>`<div class="kv"><span><span class="mono">${l[0]}</span> · ${esc(l[1])} — ${esc(l[3])}</span><b class="mono">${esc(l[2])}</b></div>`).join('')}<button class="bt" style="margin-top:10px" onclick="dumpRun()">Проверить сейчас</button></div>
 <div class="pan"><h3>Правила</h3>${[['Проверка','каждые 15 минут, 08:00–23:00'],['Если конкурент дешевле','минус шаг, не ниже порога'],['Если мы одни на 1-м месте','поднять до конкурента минус шаг'],['Если упёрлись в порог','уведомление менеджеру'],['Halyk и Forte','цена = цена аптеки, без робота']].map(x=>`<div class="kv"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></div>`;
function dumpRun(){let n=0;DUMP.forEach(d=>{if(!d.auto)return;if(d.comp<d.our&&d.our-d.step>=d.floor){const was=d.our;d.our=Math.max(d.floor,d.comp-d.step);DLOG.unshift([NOW,PR(d.p).n.split(',')[0],fmt(was)+' → '+fmt(d.our),'конкурент '+fmt(d.comp)]);d.pos=1;n++}});render();toast(n?`Цены обновлены по ${n} ${plural(n,['карточке','карточкам','карточкам'])} — в пределах порогов.`:'Всё уже на лучших позициях в пределах порогов.')}

/* ===== Остатки двух аптек ===== */
let stF='all',stQ='';
SC.stock=()=>{const S=SK.filter(inStore);let L=PRODUCTS.filter(p=>!stQ||p.n.toLowerCase().includes(stQ.toLowerCase())||p.bc.some(b=>b[0].toLowerCase().includes(stQ.toLowerCase())));
 if(stF==='low')L=L.filter(p=>S.some(s=>freeQ(p.id,s)<p.min));if(stF==='mk')L=L.filter(p=>p.mk);if(stF==='res')L=L.filter(p=>S.some(s=>reserved(p.id,s)));
 return `<div class="hd"><div><h2>Остатки ${store==='all'?'двух аптек':stName(store)}</h2><p>На полке = свободно + резерв. Резерв — товар, который лежит в заказах площадок до выдачи или возврата. Вскрытые упаковки считаются отдельно, в блистерах или пакетиках.</p></div><div class="btns"><button class="bt" onclick="go('moves')">Перемещение</button><button class="bt p" onclick="go('inventory')">Инвентаризация</button></div></div>
 <div class="filt"><input class="fin" placeholder="название или любой штрихкод" value="${esc(stQ)}" onkeydown="if(event.key==='Enter'){stQ=this.value;render()}">${[['all','Все'],['low','Ниже минимума'],['res','В резерве'],['mk','С маркировкой']].map(f=>`<button class="${stF===f[0]?'on':''}" onclick="stF='${f[0]}';render()">${f[1]}</button>`).join('')}</div>
 <div class="tw"><table class="t stk"><thead><tr><th rowspan="2">Товар</th><th rowspan="2">Группа</th>${S.map(s=>`<th colspan="4" class="c gs">${stName(s)}</th>`).join('')}<th rowspan="2" class="r">Мин.</th></tr><tr>${S.map(()=>`<th class="r">Полка</th><th class="r">Резерв</th><th class="r">Свободно</th><th class="r">Вскрыто</th>`).join('')}</tr></thead><tbody>${L.map(p=>`<tr onclick="card('pr','${p.id}')"><td>${esc(p.n)}${p.rx?' <span class="rx">Rx</span>':''}</td><td>${catm(p.cat)}</td>${S.map(s=>{const f=freeQ(p.id,s),r=reserved(p.id,s);return `<td class="r mono gs">${onHand(p.id,s)}</td><td class="r mono">${r?'<b class="acc">'+r+'</b>':'·'}</td><td class="r mono ${f<p.min?(f<=p.min/3?'neg':'warnt'):''}"><b>${f}</b></td><td class="r mono">${p.u&&p.op[s]?p.op[s]+' '+uAb(p):'·'}</td>`}).join('')}<td class="r mono">${p.min}</td></tr>`).join('')}</tbody></table></div>
 <div class="note"><b>Склад = две аптеки</b><p>Каждая аптека — отдельный склад со своими остатками, кассой и точкой выдачи на площадках. Перемещение между ними — документом, с партиями и кодами маркировки.</p></div>`};

/* ===== Партии и сроки ===== */
SC.batches=()=>{const L=BATCHES.filter(b=>inStore(b.s)&&b.q>0).sort((a,b)=>a.exp<b.exp?-1:1);
 return `<div class="hd"><div><h2>Партии и сроки годности</h2><p>Каждый приход — своя партия: серия, срок, поставщик, закупочная цена. При продаже первой списывается партия с ближайшим сроком. Себестоимость и маржа считаются по партии.</p></div></div>
 <div class="wid"><div><small>Партий в остатке</small><b>${L.length}</b></div><div><small>Срок до 60 дней</small><b class="r">${L.filter(b=>daysBetween(TODAY,b.exp)<=60).length}</b><span>${tg(L.filter(b=>daysBetween(TODAY,b.exp)<=60).reduce((a,b)=>a+b.q*b.cost,0))} по закупке</span></div><div><small>Срок 60–120 дней</small><b class="w">${L.filter(b=>{const d=daysBetween(TODAY,b.exp);return d>60&&d<=120}).length}</b></div><div><small>Склад по закупке</small><b class="a">${mln(L.reduce((a,b)=>a+b.q*b.cost,0))}</b></div><div><small>Просрочено</small><b class="g">0</b><span>просроченное не продаётся</span></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Товар</th><th>Аптека</th><th>Серия</th><th>Годен до</th><th class="r">Осталось дней</th><th class="r">Кол-во</th><th>Поставщик</th><th class="r">Закупка</th><th></th></tr></thead><tbody>${L.map(b=>{const d=daysBetween(TODAY,b.exp);return `<tr onclick="card('pr','${b.p}')"><td>${esc(PR(b.p).n)}</td><td>${stm(b.s)}</td><td class="mono">${b.no}</td><td class="mono">${dl(b.exp)}</td><td class="r mono ${d<=60?'neg':d<=120?'warnt':''}"><b>${d}</b></td><td class="r mono">${b.q}</td><td>${esc(SU(b.sup).n.replace(/ТОО |ИП /,''))}</td><td class="r mono">${fmt(b.cost)}</td><td>${d<=60?`<a class="lk" onclick="event.stopPropagation();act('expiry')">действие</a>`:''}</td></tr>`}).join('')}</tbody></table></div>`};

/* ===== Приход и накладные ===== */
let curIn='IN-0932';
SC.income=()=>{const L=INCOMES.filter(i=>inStore(i.s));const i=INCOMES.find(x=>x.id===curIn)||L[0];const su=SU(i.sup);
 return `<div class="hd"><div><h2>Приход товара и накладные</h2><p>Поставщик привёз товар — фармацевт сканирует коды, система сверяет с электронной накладной, партии и сроки встают на склад нужной аптеки, к документу прикрепляется скан накладной в PDF.</p></div><div class="btns"><button class="bt p" onclick="act('newin')">+ Приход</button></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Приход</th><th>Дата</th><th>Поставщик</th><th>Накладная</th><th>Аптека</th><th class="r">Сумма</th><th>Оплата</th><th>Скан PDF</th><th>Коды ИС МПТ</th><th>Статус</th></tr></thead><tbody>${L.map(x=>`<tr class="${x.id===i.id?'sel':''}" onclick="curIn='${x.id}';render()"><td class="mono">${x.id}</td><td class="mono">${dd(x.d)}</td><td>${esc(SU(x.sup).n)}</td><td class="mono">${x.inv}</td><td>${stm(x.s)}</td><td class="r mono">${fmt(inSum(x))}</td><td>${esc(PAYT[SU(x.sup).pay].n)}</td><td>${x.pdf?'<span class="pos">есть</span>':'<span class="neg">нет</span>'}</td><td class="mono">${x.codes[1]?x.codes[0]+' / '+x.codes[1]:'не нужны'}</td><td>${x.st==='done'?'<span class="pos">проведён</span>':'<span class="warnt">черновик</span>'}</td></tr>`).join('')}</tbody></table></div>
 <div class="g21" style="margin-top:12px"><div class="pan"><h3>${i.id} · накладная ${i.inv} от ${dl(i.d)}</h3><p>${esc(su.n)} → ${stName(i.s)} · ${esc(PAYT[su.pay].n)}${i.pay?' · '+esc(i.pay):''}</p>
  <div class="tw"><table class="t"><thead><tr><th>Товар</th><th class="r">Кол-во</th><th>Серия</th><th>Годен до</th><th class="r">Цена</th><th class="r">Сумма</th><th>НДС</th></tr></thead><tbody>${i.lines.map(l=>`<tr onclick="card('pr','${l[0]}')"><td>${esc(PR(l[0]).n)}</td><td class="r mono">${l[1]}</td><td class="mono">${l[2]}</td><td class="mono">${dl(l[3])}</td><td class="r mono">${fmt(l[4])}</td><td class="r mono">${fmt(lineSumIn(l))}</td><td class="mono">${vatOf(PR(l[0]))}%</td></tr>`).join('')}<tr class="total"><td>Итого</td><td class="r mono">${i.lines.reduce((a,l)=>a+l[1],0)}</td><td colspan="3"></td><td class="r mono">${fmt(inSum(i))}</td><td></td></tr></tbody></table></div>
  ${i.err?`<div class="note" style="--tone:var(--bad)"><b>Маркировка</b><p>${esc(i.err)}</p></div>`:''}
  ${i.st==='draft'?`<div class="btns l" style="margin-top:12px"><button class="bt ${i.pdf?'':'w'}" onclick="inPdf('${i.id}')">${i.pdf?'PDF прикреплён ✓':'Прикрепить скан PDF'}</button><button class="bt ${i.codes[0]>=i.codes[1]?'':'v'}" onclick="inCodes('${i.id}')">${i.codes[0]>=i.codes[1]?'Коды приняты ✓':'Сканировать коды · '+i.codes[0]+' / '+i.codes[1]}</button><button class="bt p" onclick="inPost('${i.id}')">Провести приход</button></div>`:''}</div>
 <div class="pan"><h3>Файлы документа</h3>${[['Электронная накладная',i.inv+' · из ИС МПТ / от поставщика',true],['Скан накладной с подписью','PDF, '+(i.pdf?'1,2 МБ':'не прикреплён'),i.pdf],['Счёт на оплату',su.pay==='pre'?'СФ поставщика · оплачен':'не нужен',su.pay==='pre'],['Договор',(CONTRACTS.find(c=>c.sup===i.sup)||{}).no||'—',true]].map(f=>`<div class="file ${f[2]?'':'no'}"><i>PDF</i><div><b>${f[0]}</b><span>${esc(f[1])}</span></div></div>`).join('')}
  ${said('«Когда приход товара будет у нас на склад, поставщик отправил товар, мы приходуем все эти товары — и возможность прикрепить к этому файл: PDF, отсканированный документ этой накладной.»')}</div></div>`};
function inPdf(id){const i=INCOMES.find(x=>x.id===id);i.pdf=true;render();toast('Скан накладной прикреплён к приходу — найдётся из архива документов и из карточки поставщика.')}
function inCodes(id){const i=INCOMES.find(x=>x.id===id);i.codes[0]=i.codes[1];render();toast('Коды DataMatrix отсканированы и приняты в ИС МПТ — товар числится за аптекой.')}
function inPost(id){const i=INCOMES.find(x=>x.id===id);if(!i.pdf||i.codes[0]<i.codes[1]){toast('Сначала прикрепите скан PDF и примите коды маркировки — без этого приход не проводится.');return}i.st='done';i.lines.forEach(l=>{PR(l[0]).st[i.s][0]+=l[1];BATCHES.push({p:l[0],s:i.s,no:l[2],exp:l[3],q:l[1],sup:i.sup,cost:l[4]})});const su=SU(i.sup);if(su.pay==='post')su.debt+=inSum(i);render();toast(`Приход проведён: ${i.lines.length} позиций на ${stName(i.s)}, партии и сроки на складе, остаток на площадках обновится через минуту.${su.pay==='post'?' Долг поставщику вырос на '+tg(inSum(i))+' — срок оплаты '+dl(addDays(TODAY,30))+'.':''}`)}

/* ===== Перемещения ===== */
SC.moves=()=>`<div class="hd"><div><h2>Перемещения между аптеками</h2><p>Если на одной аптеке закончилось, а на другой лежит — перемещение документом: что, сколько, какая партия. В пути товар не продаётся ни там, ни там; при приёмке встаёт на остаток.</p></div></div>
 <div class="g12"><div class="pan"><h3>Новое перемещение</h3><div class="form one"><label>Откуда<select id="mv_f">${SK.map(s=>`<option value="${s}">${stName(s)}</option>`).join('')}</select></label><label>Товар<select id="mv_p">${PRODUCTS.map(p=>`<option value="${p.id}">${esc(p.n)}</option>`).join('')}</select></label><label>Количество, уп.<input id="mv_q" value="5"></label></div><button class="bt p" onclick="mvNew()">Отправить</button></div>
 <div class="pan"><h3>Документы</h3><div class="tw"><table class="t"><thead><tr><th>№</th><th>Дата</th><th>Маршрут</th><th>Что</th><th>Зачем</th><th>Статус</th><th></th></tr></thead><tbody>${MOVES.map(m=>`<tr><td class="mono">${m.id}</td><td class="mono">${dd(m.d)}</td><td>${STORES[m.from].s} → ${STORES[m.to].s}</td><td>${m.lines.map(l=>esc(PR(l[0]).n.split(',')[0])+' × '+l[1]).join('<br>')}</td><td class="mini">${esc(m.why)}</td><td>${m.st==='done'?'<span class="pos">принято</span>':'<span class="warnt">в пути</span>'}</td><td>${m.st==='way'?`<button class="bt sm p" onclick="mvAccept('${m.id}')">Принять</button>`:''}</td></tr>`).join('')}</tbody></table></div></div></div>`;
function mvNew(){const f=document.getElementById('mv_f').value,p=document.getElementById('mv_p').value,q=Math.max(1,+document.getElementById('mv_q').value||1);const t=f==='A1'?'A2':'A1';if(freeQ(p,f)<q){toast(`На ${stName(f)} свободно только ${freeQ(p,f)} — остальное в резерве под заказы.`);return}PR(p).st[f][0]-=q;fefoTake(p,f,q);MOVES.unshift({id:'ПМ-0'+(42+MOVES.length-3),from:f,to:t,d:TODAY,st:'way',lines:[[p,q]],who:ROLES[role].p,why:'Создано вручную'});render();toast(`Перемещение отправлено: ${esc(PR(p).n)} × ${q}, ${STORES[f].s} → ${STORES[t].s}. В пути товар не продаётся.`)}
function mvAccept(id){const m=MOVES.find(x=>x.id===id);if(m.st!=='way')return;m.st='done';m.lines.forEach(l=>{PR(l[0]).st[m.to][0]+=l[1];const b=BATCHES.find(x=>x.p===l[0]&&x.s===m.to);if(b)b.q+=l[1];else BATCHES.push({p:l[0],s:m.to,no:'—',exp:addDays(TODAY,365),q:l[1],sup:'S1',cost:PR(l[0]).cost})});render();toast(`Перемещение ${m.id} принято на ${stName(m.to)} — остаток обновлён, на площадках тоже.`)}

/* ===== Инвентаризация ===== */
SC.inventory=()=>{const o=INVS.find(x=>x.st==='open');const L=PRODUCTS.filter(p=>p.cat==='bad'||['P07','P10'].includes(p.id));
 return `<div class="hd"><div><h2>Инвентаризация</h2><p>Полная или по полке. Фармацевт вводит факт или сканирует — система показывает разницу с учётом резерва и вскрытых упаковок. Недостача и излишки проводятся актом, история хранится.</p></div></div>
 ${o?`<div class="pan"><h3>${o.id} · ${stName(o.s)} · ${esc(o.zone)} · идёт сейчас</h3><div class="tw"><table class="t"><thead><tr><th>Товар</th><th class="r">По учёту</th><th class="r">В т. ч. резерв</th><th class="r">Факт</th><th class="r">Разница</th></tr></thead><tbody>${L.map(p=>`<tr><td>${esc(p.n)}</td><td class="r mono">${onHand(p.id,o.s)}</td><td class="r mono">${reserved(p.id,o.s)||'·'}</td><td class="r"><input class="qin" id="iv_${p.id}" value="${p.id==='P08'?onHand(p.id,o.s)-1:onHand(p.id,o.s)}" oninput="ivDiff()"></td><td class="r mono" id="ivd_${p.id}">${p.id==='P08'?'<b class="neg">−1</b>':'0'}</td></tr>`).join('')}</tbody></table></div>
  <div class="btns l" style="margin-top:12px"><button class="bt p" onclick="ivPost()">Провести акт</button><span class="mini">Резерв считается: товар в пакете заказа — это не недостача.</span></div></div>`:'<div class="pan"><p class="mini">Открытых инвентаризаций нет.</p></div>'}
 <div class="pan"><h3>Проведённые</h3>${INVS.filter(x=>x.st==='done').map(x=>`<div class="kv"><span><span class="mono">${x.id}</span> · ${dl(x.d)} · ${stName(x.s)} · ${esc(x.zone)}</span><b>${x.diff.map(d=>esc(PR(d[0]).n.split(',')[0])+' '+(d[1]>0?'+':'')+d[1]).join('; ')||'без расхождений'}</b></div>`).join('')}</div>`};
function ivDiff(){const o=INVS.find(x=>x.st==='open');PRODUCTS.forEach(p=>{const i=document.getElementById('iv_'+p.id);if(!i)return;const d=(+i.value||0)-onHand(p.id,o.s);document.getElementById('ivd_'+p.id).innerHTML=d?`<b class="${d<0?'neg':'pos'}">${d>0?'+':''}${d}</b>`:'0'})}
function ivPost(){const o=INVS.find(x=>x.st==='open');const D=[];PRODUCTS.forEach(p=>{const i=document.getElementById('iv_'+p.id);if(!i)return;const d=(+i.value||0)-onHand(p.id,o.s);if(d){D.push([p.id,d,d<0?'недостача':'излишек']);p.st[o.s][0]+=d}});o.diff=D;o.st='done';render();toast(D.length?`Акт ${o.id} проведён: ${D.length} ${plural(D.length,['расхождение','расхождения','расхождений'])}, остатки исправлены.`:'Акт проведён без расхождений.')}

/* ===== Номенклатура ===== */
let catF='all';
SC.catalog=()=>{const L=PRODUCTS.filter(p=>catF==='all'||p.cat===catF);
 return `<div class="hd"><div><h2>Номенклатура</h2><p>Карточка товара: название, производитель, группа, фасовка, минимальный остаток и <b>сколько угодно штрихкодов и артикулов</b> — заводской, старой упаковки, артикулы каждого поставщика, SKU площадок. Сканер найдёт товар по любому из них.</p></div><div class="btns"><button class="bt" onclick="act('import')">Импорт из Excel / текущей программы</button><button class="bt p" onclick="card('newpr')">+ Новый товар</button></div></div>
 <div class="filt"><button class="${catF==='all'?'on':''}" onclick="catF='all';render()">Все · ${PRODUCTS.length}</button>${Object.keys(CATS).map(k=>`<button class="${catF===k?'on':''}" onclick="catF='${k}';render()">${CATS[k].n} · ${PRODUCTS.filter(p=>p.cat===k).length}</button>`).join('')}</div>
 <div class="tw"><table class="t"><thead><tr><th>Товар</th><th>Группа</th><th>Фасовка / деление</th><th class="r">Кодов</th><th>НДС</th><th>НКТ</th><th>Маркировка</th><th class="r">Закупка</th><th class="r">Цена</th><th class="r">Маржа</th><th>Площадки</th></tr></thead><tbody>${L.map(p=>`<tr onclick="card('pr','${p.id}')"><td>${esc(p.n)}${p.rx?' <span class="rx">Rx</span>':''}<span class="sub">${esc(p.mf)}</span></td><td>${catm(p.cat)}</td><td>${p.u?`1 уп. = ${p.u[1]} ${p.u[0]==='блистер'?'бл.':p.u[0]==='пакетик'?'пак.':'шт.'} · ${fmt(p.u[2])} ₸`:'<span class="mini">не делится</span>'}</td><td class="r mono"><b>${p.bc.length}</b></td><td class="mono">${vatOf(p)}%</td><td>${p.nkt==='ok'?'<span class="pos">есть</span>':p.nkt==='wait'?'<span class="warnt">модерация</span>':'<span class="neg">нет</span>'}</td><td>${p.mk?'<span class="mkm">DataMatrix</span>':'<span class="mini">—</span>'}</td><td class="r mono">${fmt(p.cost)}</td><td class="r mono">${fmt(p.price)}</td><td class="r mono">${pct(p.price-p.cost,p.price)}%</td><td>${p.mpl.map(mpm).join(' ')||'<span class="mini">—</span>'}</td></tr>`).join('')}</tbody></table></div>
 ${said('«Отдельно название товара плюс штрихкод… возможность этому товару добавить несколько артикулов — не один, а сразу пять, шесть, сколько получится.»','Парацетамол в демо — 6 кодов: заводской, старая упаковка, два артикула поставщиков, Kaspi и Halyk.')}`};
function addBc(id){const v=document.getElementById('nbc').value.trim(),w=document.getElementById('nbw').value;if(!v){toast('Введите код.');return}const f=findBc(v);if(f){toast(`Этот код уже привязан к «${esc(f[0].n)}» — двойных кодов система не допустит.`);return}PR(id).bc.push([v,w]);card('pr',id);render();toast('Код добавлен — сканер и поиск уже находят товар по нему.')}

/* ===== Разукомплектация ===== */
let unLog=[['30.09 18:05','A1','P01','1 уп. → 2 блистера','Асель'],['30.09 12:40','A2','P16','1 уп. → 10 пакетиков','Динара'],['29.09 20:15','A1','P07','1 уп. → 5 блистеров','Асель']];
SC.unpack=()=>{const L=PRODUCTS.filter(p=>p.u);const S=SK.filter(inStore);
 return `<div class="hd"><div><h2>Разукомплектация</h2><p>В коробке два блистера по десять таблеток — клиенту нужен один. Фармацевт продаёт блистер, система сама вскрывает упаковку: на полке становится на 1 упаковку меньше и +2 блистера. Партия, срок и себестоимость переходят на блистеры.</p></div></div>
 <div class="unf"><div><small>было</small><b>1 упаковка</b><span>Парацетамол №20 · 290 ₸</span></div><i>→</i><div><small>вскрыли</small><b>2 блистера × 10</b><span>по 160 ₸ за блистер</span></div><i>→</i><div class="ok"><small>продали один</small><b>1 блистер на полке</b><span>остаток: упаковки + 1 бл.</span></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Товар</th><th>Деление</th><th class="r">Цена уп.</th><th class="r">Цена ед.</th><th class="r">Маржа ед.</th>${S.map(s=>`<th class="r">${STORES[s].s}: уп. / вскрыто</th>`).join('')}<th></th></tr></thead><tbody>${L.map(p=>`<tr onclick="card('pr','${p.id}')"><td>${esc(p.n)}</td><td>1 уп. = ${p.u[1]} ${uPl(p,p.u[1])}</td><td class="r mono">${fmt(p.price)}</td><td class="r mono">${fmt(p.u[2])}</td><td class="r mono">${pct(p.u[2]-p.cost/p.u[1],p.u[2])}%</td>${S.map(s=>`<td class="r mono">${onHand(p.id,s)} / ${p.op[s]||'·'}</td>`).join('')}<td onclick="event.stopPropagation()">${S.map(s=>`<button class="bt sm" onclick="unpack('${p.id}','${s}')">Вскрыть на ${STORES[s].s}</button>`).join(' ')}</td></tr>`).join('')}</tbody></table></div>
 <div class="g2" style="margin-top:12px"><div class="pan"><h3>Журнал вскрытий</h3>${unLog.map(l=>`<div class="kv"><span><span class="mono">${l[0]}</span> · ${STORES[l[1]].s} · ${esc(PR(l[2]).n.split(',')[0])} · ${esc(l[4])}</span><b>${esc(l[3])}</b></div>`).join('')}</div>
 <div class="pan"><h3>Маркировка при делении</h3><p class="mini">Код DataMatrix стоит на упаковке. При вскрытии система отмечает упаковку в ИС МПТ по правилам частичной продажи — точный порядок для лекарств и БАДов сверим с регламентом при подключении, чтобы аптека не получила расхождение.</p></div></div>
 ${said('«В упаковке два блистера по десять штук, полная коробка не нужна, нужен только один блистер — возможно сделать разукомплектацию?»')}`};
function unpack(id,s){const p=PR(id);if(freeQ(id,s)<1){toast('Свободных упаковок нет — всё в резерве.');return}p.st[s][0]--;fefoTake(id,s,1);p.op[s]+=p.u[1];unLog.unshift([dd(TODAY)+' '+NOW,s,id,`1 уп. → ${p.u[1]} ${p.u[0]==='блистер'?plural(p.u[1],['блистер','блистера','блистеров']):p.u[0]==='пакетик'?plural(p.u[1],['пакетик','пакетика','пакетиков']):'шт.'}`,STAFF[ROLES[role].p]]);render();toast(`Вскрыта упаковка «${esc(p.n.split(',')[0])}» на ${STORES[s].s}: −1 уп., +${p.u[1]} ${esc(p.u[0])}. Продаются по ${tg(p.u[2])}.`)}

/* ===== Ставки НДС ===== */
SC.vat=()=>{const ex=[['P01',2],['P09',1],['P13',1]];const r27=items=>{const r={};items.forEach(i=>{const p=PR(i[0]),v=vatOn(p.cat,'2027-01-01');r[v]=(r[v]||0)+lineSum(i)});return r};
 return `<div class="hd"><div><h2>Ставки НДС</h2><p>Ставка задаётся группе товаров и привязана к дате. Лекарства — 5% в 2026 году и 10% с 1 января 2027; остальное — 16%. Новая ставка включится сама в нужный день, в чеке НДС разбивается по ставкам.</p></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Группа</th><th class="r">Товаров</th><th>2026</th><th>С 01.01.2027</th><th>Комментарий</th></tr></thead><tbody>${VAT.map(v=>`<tr><td><b>${esc(v.n)}</b></td><td class="r mono">${PRODUCTS.filter(p=>p.cat===v.k).length}</td><td class="mono"><b>${vatOn(v.k,'2026-06-01')}%</b></td><td class="mono"><b class="${vatOn(v.k,'2027-01-01')!==vatOn(v.k,'2026-06-01')?'warnt':''}">${vatOn(v.k,'2027-01-01')}%</b></td><td class="mini">${esc(v.note)}</td></tr>`).join('')}</tbody></table></div>
 <div class="g2" style="margin-top:12px"><div class="pan"><h3>Пример чека сегодня</h3>${ex.map(i=>`<div class="kv"><span>${esc(PR(i[0]).n)} × ${i[1]} · НДС ${vatOf(PR(i[0]))}%</span><b class="mono">${fmt(lineSum(i))}</b></div>`).join('')}<div class="kv big"><span>Итого</span><b>${tg(ex.reduce((a,i)=>a+lineSum(i),0))}</b></div>${Object.entries(vatSplit(ex)).map(([k,v])=>`<div class="kv"><span>в т. ч. НДС ${k}%</span><b class="mono">${fmt(vatSum(v,+k))}</b></div>`).join('')}</div>
 <div class="pan"><h3>Тот же чек с 1 января 2027</h3>${ex.map(i=>`<div class="kv"><span>${esc(PR(i[0]).n)} × ${i[1]} · НДС ${vatOn(PR(i[0]).cat,'2027-01-01')}%</span><b class="mono">${fmt(lineSum(i))}</b></div>`).join('')}<div class="kv big"><span>Итого</span><b>${tg(ex.reduce((a,i)=>a+lineSum(i),0))}</b></div>${Object.entries(r27(ex)).map(([k,v])=>`<div class="kv"><span>в т. ч. НДС ${k}%</span><b class="mono">${fmt(vatSum(v,+k))}</b></div>`).join('')}<p class="mini" style="margin-top:8px">Цена не меняется сама — система покажет, как изменится маржа, а вы решите: оставить цену или поднять. Ставки по каждой группе подтверждает ваш бухгалтер.</p></div></div>
 ${said('«Обычные товары — НДС шестнадцать процентов, а лекарственные средства облагаются пятипроцентным в этом году, после — десять процентов.»')}`};

/* ===== НКТ ===== */
SC.nkt=()=>{const L=PRODUCTS.slice().sort((a,b)=>(a.nkt==='ok')-(b.nkt==='ok'));
 return `<div class="hd"><div><h2>Национальный каталог товаров</h2><p>Каждая карточка сверяется с НКТ по GTIN: наименование, производитель, форма выпуска. Пока карточки нет — товар не публикуется на площадках и не принимается по маркировке. Статусы подтягиваются автоматически.</p></div><div class="btns"><button class="bt" onclick="act('nktsync')">Сверить всё с НКТ</button></div></div>
 <div class="wid"><div><small>Есть в НКТ</small><b class="g">${PRODUCTS.filter(p=>p.nkt==='ok').length}</b></div><div><small>На модерации</small><b class="w">${PRODUCTS.filter(p=>p.nkt==='wait').length}</b></div><div><small>Нет карточки</small><b class="r">${PRODUCTS.filter(p=>p.nkt==='no').length}</b></div><div><small>Блокирует площадки</small><b>${PRODUCTS.filter(p=>p.nkt!=='ok'&&p.mpl.length).length}</b></div><div><small>Последняя сверка</small><b class="mono" style="font-size:18px">13:20</b></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Товар</th><th>GTIN</th><th>Группа</th><th>Статус НКТ</th><th>Что блокирует</th><th></th></tr></thead><tbody>${L.map(p=>`<tr onclick="card('pr','${p.id}')"><td>${esc(p.n)}</td><td class="mono">${p.gtin||'—'}</td><td>${catm(p.cat)}</td><td>${p.nkt==='ok'?'<span class="pos">карточка есть</span>':p.nkt==='wait'?'<span class="warnt">на модерации</span>':'<span class="neg">нет карточки</span>'}</td><td class="mini">${p.nkt==='ok'?'—':(p.mpl.length?'публикация на '+p.mpl.map(k=>MP[k].s).join(', '):'продажа на площадках')+(p.mk?', приёмка кодов':'')}</td><td onclick="event.stopPropagation()">${p.nkt==='no'?`<button class="bt sm p" onclick="PR('${p.id}').nkt='wait';render();toast('Заявка на карточку отправлена в НКТ. Статус придёт автоматически.')">Создать карточку</button>`:p.nkt==='wait'?`<button class="bt sm" onclick="PR('${p.id}').nkt='ok';render();toast('НКТ: карточка одобрена — товар опубликуется на площадках при следующей синхронизации.')">Проверить статус</button>`:''}</td></tr>`).join('')}</tbody></table></div>
 ${said('«Национальный каталог товаров — немаловажно, по законодательству нужно, чтобы НКТ было подключено.»')}`};

/* ===== Маркировка ИС МПТ ===== */
let MKLOG=[
 ['14:02','A1','Выбытие · продажа','ФЧ-1-018824 · Парацетамол, 1 блистер','ok'],
 ['13:58','A2','Выбытие · продажа','ФЧ-2-007417 · Диосмектит, 2 пакетика','wait'],
 ['12:30','A1','Выбытие · заказ выдан','614497203 · Ибупрофен, Аскорбиновая кислота','ok'],
 ['11:15','A2','Выбытие · заказ выдан','HM-240871 · Омега-3 × 2','ok'],
 ['10:20','A2','Перемещение','ПМ-041 · Нафазолин × 8 → аптека №1','ok'],
 ['30.09 17:10','A2','Приёмка','ВМ-Н-2207 «Витамакс» · 19 из 20 кодов','err'],
 ['30.09 10:20','A2','Возврат в оборот','614493317 — отказ до выдачи, коды не выбывали','ok'],
 ['30.09 09:05','A1','Приёмка','ФЛ-58213 «Фармлайн» · 44 из 44','ok']
];
SC.marking=()=>`<div class="hd"><div><h2>Маркировка · ИС МПТ</h2><p>Лекарства и с 1 сентября БАДы — с кодом DataMatrix. Приёмка кодов от поставщика, выбытие при выдаче заказа или продаже в аптеке, перемещения между аптеками. Отказ до выдачи кодов не трогает — они не выбывали.</p></div><div class="btns"><button class="bt" onclick="card('int','ismp')">Подключение</button></div></div>
 <div class="wid"><div><small>Кодов на балансе №1</small><b>${fmt(PRODUCTS.filter(p=>p.mk).reduce((a,p)=>a+onHand(p.id,'A1'),0))}</b></div><div><small>Кодов на балансе №2</small><b>${fmt(PRODUCTS.filter(p=>p.mk).reduce((a,p)=>a+onHand(p.id,'A2'),0))}</b></div><div><small>Выбыло сегодня</small><b class="g">${MKLOG.filter(l=>l[0].indexOf('.')<0&&l[2].indexOf('Выбытие')===0).length}</b></div><div><small>Ошибки</small><b class="r">${MKLOG.filter(l=>l[4]==='err').length}</b><span>разбираются с поставщиком</span></div><div><small>БАДы с маркировкой</small><b class="w">${PRODUCTS.filter(p=>p.cat==='bad'&&p.mk).length}</b><span>с 01.09.2026</span></div></div>
 <div class="g21"><div class="pan"><h3>События</h3><div class="tw"><table class="t"><thead><tr><th>Время</th><th>Аптека</th><th>Операция</th><th>Документ</th><th>ИС МПТ</th></tr></thead><tbody>${MKLOG.filter(l=>inStore(l[1])).map(l=>`<tr><td class="mono">${l[0]}</td><td>${stm(l[1])}</td><td>${esc(l[2])}</td><td>${esc(l[3])}</td><td>${l[4]==='ok'?'<span class="pos">принято</span>':l[4]==='wait'?'<span class="warnt">отправляется</span>':'<span class="neg">ошибка</span>'}</td></tr>`).join('')}</tbody></table></div></div>
 <div class="pan"><h3>Когда что уходит в ИС МПТ</h3>${[['Приход от поставщика','приёмка кодов по накладной'],['Резерв под заказ','ничего — код в обороте'],['Заказ выдан','выбытие вместе с фискальным чеком'],['Отказ до выдачи','ничего — код не выбывал'],['Возврат после выдачи','возврат в оборот по чеку возврата'],['Перемещение №1 ↔ №2','смена места хранения'],['Вскрытие упаковки','по правилам частичной продажи']].map(x=>`<div class="kv"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></div>
 ${said('«Интеграция ИС МПТ — маркировка лекарственных средств… Первого сентября ввели БАДы тоже — маркировку.»')}`;

