SC.suppliers=()=>`<div class="hd"><div><h2>Поставщики и оплаты</h2><p>У каждого поставщика свой порядок: предоплата по счёту, отсрочка или консигнация. Система ведёт, что и когда платить: счёт к оплате, срок отсрочки по накладной, по консигнации — только за проданное.</p></div></div>
 <div class="sups">${SUPPLIERS.map(s=>`<div class="sup" style="--c:${PAYT[s.pay].c}" onclick="card('sup','${s.id}')"><small>${esc(PAYT[s.pay].n)}</small><b>${esc(s.n)}</b><span>${esc(s.term)}</span><div class="kv"><span>${s.pay==='cons'?'К оплате за проданное':s.pay==='post'?'Долг по отсрочке':'Счёт к оплате'}</span><b class="mono">${fmt(s.pay==='pre'?s.pend:s.debt)}</b></div>${s.cons?`<div class="kv"><span>На реализации у нас</span><b class="mono">${fmt(s.cons)}</b></div>`:''}<div class="kv"><span>Доля закупок</span><b class="mono">${s.share}%</b></div></div>`).join('')}</div>
 <div class="pan"><h3>Календарь оплат</h3><div class="tw"><table class="t"><thead><tr><th>Срок</th><th>Поставщик</th><th>Основание</th><th>Тип</th><th class="r">Сумма</th><th></th></tr></thead><tbody>${PAYS.slice().sort((a,b)=>a.due<b.due?-1:1).map(p=>{const d=daysBetween(TODAY,p.due);return `<tr onclick="card('sup','${p.sup}')"><td class="mono ${p.st==='open'&&d<=0?'neg':p.st==='open'&&d<=3?'warnt':''}">${dl(p.due)}${p.st==='open'?(d<0?' · просрочено':d===0?' · сегодня':' · через '+d+' дн.'):''}</td><td>${esc(SU(p.sup).n)}</td><td>${esc(p.what)}</td><td>${esc(PAYT[SU(p.sup).pay].n)}</td><td class="r mono">${fmt(p.sum)}</td><td onclick="event.stopPropagation()">${p.st==='paid'?'<span class="pos">оплачено</span>':`<button class="bt sm p" onclick="payDo('${p.id}')">Оплачено</button>`}</td></tr>`}).join('')}</tbody></table></div></div>
 ${said('«Кто-то сначала отправляет счёт на оплату, после этого мы оплачиваем, и нам отправляют товары. Есть консигнация — сначала товар отправляют, и потом оплачиваем.»')}`;
function payDo(id){const p=PAYS.find(x=>x.id===id);p.st='paid';const s=SU(p.sup);if(s.pay==='pre')s.pend=Math.max(0,s.pend-p.sum);else s.debt=Math.max(0,s.debt-p.sum);render();toast(`Оплата ${tg(p.sum)} отмечена — ${esc(s.n)}. ${s.pay==='pre'?'Поставщик получит уведомление в WhatsApp, ждём отгрузку.':'Долг уменьшен.'}`)}

