  <div class="phone"><div class="pht"><b>Ерлан · день</b><small>${dl(TODAY)}, ${NOW}</small></div><div class="pb">${[['Выручка по чекам',tg(CHECKS.reduce((a,c)=>a+cSum(c),0))],['Новых заказов',ORDERS.filter(o=>o.st==='new').length],['В доставке',ORDERS.filter(o=>o.st==='courier').length],['Отказов в пути',R.length],['Оплатить сегодня',tg(PAYS.filter(p=>p.st==='open'&&p.due<=TODAY).reduce((a,p)=>a+p.sum,0))]].map(x=>`<div class="pi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}<div class="pbtn" onclick="go('today')">Открыть пульт</div></div></div>
